var DATA = {"mode": "osd", "what": "frame ledger + telemetry", "where": "over the game"};
function show(k,v){console.log(k+": "+v);}
var m=DATA.mode;
if(m==="osd"){
  show("Tool","RivaTuner Statistics Server - on-screen display");
  show("Shows",DATA.what);show("Position",DATA.where);
}else if(m==="fps"){
  show("Frame time",DATA.ms+" ms");
  show("Equals FPS",Math.round(1000/DATA.ms*10)/10);
}else if(m==="frametime"){
  var ts=DATA.times;
  var avg=Math.round(ts.reduce(function(a,b){return a+b;},0)/ts.length*100)/100;
  var mx=Math.max.apply(null,ts);
  show("Average",avg+" ms = "+Math.round(1000/avg*10)/10+" FPS");
  show("Worst frame",mx+" ms");
  show("Stutter",mx>avg*1.5?"YES - worst far over average":"smooth");
}else if(m==="limiter"){
  show("Cap",DATA.fps+" FPS");
  show("Frame budget",(Math.round(1000/DATA.fps*100)/100)+" ms per frame");
  show("Why","smoother pacing, less power, less heat");
}else if(m==="scanline"){
  show("Scanline sync","tear-free with less lag than vsync");
  show("Setup","one-time tearline calibration per display");
}else if(m==="profiles"){
  show("Profiles",DATA.n+" per-application");
  show("Example",DATA.ex);
}else if(m==="hotkeys"){
  show("Hotkeys","toggle OSD, toggle limiter, capture");
}else if(m==="capture"){
  show("Capture","screenshots and video via encoder server");
}else if(m==="stealth"){
  show("Stealth mode","hides the OSD from captures and streams");
}else if(m==="layout"){
  show("Layout",DATA.layout);show("Editor","visual, drag and arrange");
}else if(m==="items"){
  console.log("Overlay items:");
  DATA.items.forEach(function(i){console.log("  "+i);});
}else if(m==="stats"){
  show("Session average",DATA.avg+" FPS");
  show("1% low",DATA.low+" FPS");
  show("Read","lows tell the stutter story averages hide");
}else if(m==="compare"){
  show("RTSS limiter","precise frame pacing, tiny overhead");
  show("In-engine cap","quality varies by game");
}else if(m==="workflow"){
  console.log("Overlay workflow:");
  DATA.steps.forEach(function(s,i){console.log("  "+(i+1)+". "+s);});
}
console.log("DEMO_OK");

